import { useState, useEffect } from "react";
import { Save } from "lucide-react";
import { fieldClass, buttonClass, warpCategories } from "./adminShared";

function SurveyCategory({ warp, busy, readOnly, onAssign }) {
  const [category, setCategory] = useState(warp.warpCategory || "");
  useEffect(() => setCategory(warp.warpCategory || ""), [warp.warpCategory]);
  if (readOnly) return <div className="text-[10px] text-zinc-500 mt-3">{warp.warpCategory ? `Category: ${warp.warpCategory}` : "Category not set"}</div>;
  return <div className="flex gap-2 mt-3">
    <select aria-label={`Survey category for ${warp.warpName}`} className={fieldClass} value={category} onChange={(event) => setCategory(event.target.value)}>
      {warpCategories.map(([value, label]) => <option key={value || "unclassified"} value={value}>{label}</option>)}
    </select>
    <button disabled={busy || category === (warp.warpCategory || "")} onClick={() => onAssign(warp, category)} className={`${buttonClass} bg-emerald-500 text-black`}><Save /></button>
  </div>;
}

export default SurveyCategory;
