import { useCallback, useEffect, useState } from "react";
import { AlertTriangle, Loader2, LogOut, RefreshCw } from "lucide-react";
import { toast } from "sonner";
import Header from "@/components/landing/Header";
import Footer from "@/components/landing/Footer";
import SEO from "@/components/ui/SEO";
import LoginPanel from "@/components/admin/LoginPanel";
import AdminConsole from "@/components/admin/AdminConsole";
import { buttonClass } from "@/components/admin/adminShared";
import { adminAuth, getAdminSession, onAdminAuthChange, signOutAdmin } from "@/lib/adminAuth";
import { fetchAdminDashboard, fetchAdminShopMaps } from "@/lib/adminClient";














export default function AdminPage() {
  const [session, setSession] = useState(null);
  const [checking, setChecking] = useState(true);
  const [dashboard, setDashboard] = useState(null);
  const [shopMaps, setShopMaps] = useState(null);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);
  const [busy, setBusy] = useState(false);

  useEffect(() => {
    let mounted = true;
    getAdminSession().then((next) => mounted && setSession(next)).catch(() => {}).finally(() => mounted && setChecking(false));
    const unsubscribe = onAdminAuthChange((next) => { if (mounted) { setSession(next); setChecking(false); } });
    return () => { mounted = false; unsubscribe(); };
  }, []);

  const load = useCallback(async () => {
    if (!session) return;
    setLoading(true); setError(null);
    try { const [nextDashboard, nextMaps] = await Promise.all([fetchAdminDashboard(), fetchAdminShopMaps()]); setDashboard(nextDashboard); setShopMaps(nextMaps); }
    catch (nextError) { setError(nextError); if (nextError.status === 401) await adminAuth.auth.signOut({ scope: "local" }); }
    finally { setLoading(false); }
  }, [session]);

  useEffect(() => { load(); }, [load]);

  const perform = async (action, success) => {
    setBusy(true);
    try { await action(); toast.success(success); await load(); return true; }
    catch (nextError) { toast.error("Change was not saved", { description: nextError.message }); return false; }
    finally { setBusy(false); }
  };

  return <div data-testid="admin-page" className="min-h-screen bg-bg-base text-white font-body">
    <SEO title="Administration" description="Restricted Castia Market Insight administration." noindex />
    <Header />
    {checking ? <main className="min-h-[78vh] grid place-items-center"><Loader2 className="w-7 h-7 animate-spin text-emerald-400" /></main>
      : !session ? <LoginPanel />
      : error ? <main className="min-h-[78vh] pt-32 px-6"><div className="max-w-lg mx-auto rounded-xl border border-red-500/30 bg-red-500/10 p-6"><AlertTriangle className="text-red-400 mb-3" /><h1 className="font-heading text-2xl font-bold">Admin access unavailable</h1><p className="text-sm text-zinc-400 mt-2">{error.status === 403 ? "This account is signed in but is not on the administrator allowlist." : error.message}</p><div className="flex gap-2 mt-5"><button className={`${buttonClass} bg-emerald-500 text-black`} onClick={load}><RefreshCw /> Retry</button><button className={`${buttonClass} border border-white/10`} onClick={() => signOutAdmin()}><LogOut /> Sign out</button></div></div></main>
      : dashboard && shopMaps ? <AdminConsole dashboard={dashboard} shopMaps={shopMaps} loading={loading} busy={busy} onRefresh={load} onAction={perform} onSignOut={() => signOutAdmin()} />
      : <main className="min-h-[78vh] grid place-items-center"><Loader2 className="w-7 h-7 animate-spin text-emerald-400" /></main>}
    <Footer />
  </div>;
}
