import { useState, useEffect } from "react";
import { Save } from "lucide-react";
import { fieldClass, buttonClass, warpCategories } from "./adminShared";

function WarpRow({ warp, areas, readOnly, busy, onAssign }) {
  const [areaId, setAreaId] = useState(warp.shopAreaId || "");
  const [category, setCategory] = useState(warp.warpCategory || "");
  const [reason, setReason] = useState("");
  useEffect(() => { setAreaId(warp.shopAreaId || ""); setCategory(warp.warpCategory || ""); }, [warp.shopAreaId, warp.warpCategory]);
  const changed = areaId !== (warp.shopAreaId || "") || category !== (warp.warpCategory || "");
  const compatible = areas.filter((area) => area.serverKey === warp.serverKey && area.dimensionKey === warp.dimensionKey);
  return <div className="grid lg:grid-cols-[minmax(150px,1.4fr)_100px_110px_130px_140px] gap-2 lg:gap-3 items-center p-3 border-b border-white/[0.06] last:border-0">
    <div className="min-w-0"><div className="font-mono text-sm text-zinc-200 truncate">/pw {warp.warpName}</div><div className="text-[10px] text-zinc-500 truncate">{warp.owner || "Unknown owner"} · {warp.centerX}, {warp.centerY}, {warp.centerZ}</div></div>
    <div className="text-xs text-zinc-400">{warp.signCount} signs · {warp.sellerCount} sellers</div>
    <span className={`w-fit text-[9px] uppercase tracking-wider font-mono px-2 py-1 rounded-full border ${warp.status === "assigned" ? "border-emerald-500/20 text-emerald-300" : warp.status === "needs_scan" ? "border-amber-500/20 text-amber-300" : "border-indigo-500/20 text-indigo-300"}`}>{warp.status.replace("_", " ")}</span>
    <select aria-label={`Category for ${warp.warpName}`} className={fieldClass} value={category} disabled={readOnly} onChange={(event) => { const next = event.target.value; setCategory(next); if (next !== "shops") setAreaId(""); }}>
      {warpCategories.map(([value, label]) => <option key={value || "unclassified"} value={value}>{label}</option>)}
    </select>
    <select aria-label={`Area for ${warp.warpName}`} className={fieldClass} value={areaId} disabled={readOnly || category !== "shops"} onChange={(e) => setAreaId(e.target.value)}>
      <option value="">Independent / unassigned</option>
      {compatible.map((area) => <option key={area.id} value={area.id}>{area.name}</option>)}
    </select>
    {!readOnly && <div className="flex gap-2 min-w-0 lg:col-span-full lg:mt-1"><input aria-label={`Reason for ${warp.warpName}`} className={`${fieldClass} min-w-0 flex-1`} value={reason} onChange={(e) => setReason(e.target.value)} placeholder="Optional note" maxLength={500} />
      <button disabled={!changed || busy} onClick={() => onAssign(warp, areaId || null, category || null, reason.trim() || "Manual warp assignment update.")} className={`${buttonClass} bg-emerald-500 text-black shrink-0`}><Save /></button></div>}
  </div>;
}

export default WarpRow;
