import { useEffect, useMemo, useState } from "react";
import { AlertTriangle, CheckCircle2, ChevronDown, ChevronUp, Clock3, Eye, Image, Loader2, RotateCcw, Trash2, UploadCloud } from "lucide-react";
import { createShopMapDraft, deleteShopMap, fetchShopMapPreviewTile, finalizeShopMap, publishShopMap, rollbackShopMap, uploadShopMapTile } from "@/lib/adminClient";
import { readShopMapBundle } from "@/lib/shopMapBundle";

const button = "inline-flex items-center justify-center gap-2 rounded-md px-3 py-2 text-xs font-bold uppercase tracking-wider transition-colors disabled:pointer-events-none disabled:opacity-40";

const layerKey = tile => tile.layerKind === "surface" ? "surface" : `cave:${tile.caveLayer}`;
const caveRenderY = tile => tile.renderY ?? tile.caveLayer * 16 + 8;
const formatDate = value => {
  if (!value) return "Unknown";
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? "Unknown" : date.toLocaleString();
};

function layerOptions(manifest) {
  const byKey = new Map();
  for (const tile of manifest?.tiles || []) {
    const key = layerKey(tile);
    if (!byKey.has(key)) byKey.set(key, {
      key,
      kind: tile.layerKind,
      caveLayer: tile.caveLayer,
      renderY: tile.layerKind === "cave" ? caveRenderY(tile) : null,
      tiles: [],
    });
    byKey.get(key).tiles.push(tile);
  }
  return [...byKey.values()].sort((a, b) => a.kind === b.kind ? (a.renderY ?? 0) - (b.renderY ?? 0) : a.kind === "surface" ? -1 : 1);
}

function MapPreview({ bundle, version }) {
  const manifest = bundle?.manifest || version?.manifest;
  const options = useMemo(() => layerOptions(manifest), [manifest]);
  const [selected, setSelected] = useState("surface");
  const [urls, setUrls] = useState(new Map());
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const active = options.find(option => option.key === selected) || options[0];

  useEffect(() => {
    setSelected(options.some(option => option.key === "surface") ? "surface" : options[0]?.key || "surface");
  }, [bundle, version?.id, options]);

  useEffect(() => {
    if (!active) { setUrls(new Map()); return undefined; }
    const controller = new AbortController();
    let created = [];
    setLoading(true);
    setError(null);
    Promise.all(active.tiles.map(async tile => {
      const blob = bundle
        ? new Blob([bundle.files.get(tile.filename)], { type: "image/png" })
        : await fetchShopMapPreviewTile(version.id, tile.filename, { signal: controller.signal });
      const url = URL.createObjectURL(blob);
      created.push(url);
      return [tile.filename, url];
    })).then(entries => {
      if (controller.signal.aborted) return;
      setUrls(new Map(entries));
    }).catch(next => {
      if (!controller.signal.aborted) setError(next.message || "Map preview could not be loaded.");
    }).finally(() => {
      if (!controller.signal.aborted) setLoading(false);
    });
    return () => {
      controller.abort();
      for (const url of created) URL.revokeObjectURL(url);
    };
  }, [active, bundle, version]);

  const bounds = manifest?.bounds;
  if (!bounds || !active) return <div className="rounded-xl border border-dashed border-white/10 p-8 text-center text-xs text-zinc-500">Preview metadata is unavailable.</div>;
  const width = bounds.maxX - bounds.minX;
  const height = bounds.maxZ - bounds.minZ;
  const marker = Math.max(2, Math.min(10, Math.max(width, height) / 90));
  const allSigns = manifest.capturePlan?.signs || [];
  const signs = active.kind === "surface" ? allSigns : allSigns.filter(sign => Math.floor(sign.y / 16) === active.caveLayer);
  const warps = manifest.capturePlan?.warps || [];

  return <div className="theme-dark-island overflow-hidden rounded-xl border border-white/10 bg-[#080c10] p-3">
    <div className="mb-3 flex flex-wrap items-center justify-between gap-2">
      <div className="flex items-center gap-2 text-xs text-zinc-400"><Eye className="h-3.5 w-3.5 text-indigo-300" /> Publication preview</div>
      {options.length > 1 && <select aria-label="Preview map layer" className="rounded-md border border-white/10 bg-bg-base px-2 py-1.5 text-xs text-zinc-300" value={active.key} onChange={event => setSelected(event.target.value)}>
        {options.map(option => <option key={option.key} value={option.key}>{option.kind === "surface" ? "Surface overview" : `Layered cave · Y ${option.renderY}`}</option>)}
      </select>}
    </div>
    <div className="relative min-h-48">
      {loading && <div className="absolute inset-0 z-10 grid place-items-center bg-black/40"><Loader2 className="animate-spin text-indigo-300" /></div>}
      {error ? <div role="alert" className="grid min-h-48 place-items-center rounded bg-red-500/[0.06] px-5 text-center text-xs text-red-200">{error}</div> : <svg viewBox={`${bounds.minX} ${bounds.minZ} ${width} ${height}`} role="img" aria-label={`${active.kind === "surface" ? "Surface" : "Layered cave"} map preview with shop signs and warp arrivals`} className="mx-auto block max-h-[28rem] w-full rounded bg-black/30" preserveAspectRatio="xMidYMid meet">
        <title>{active.tiles.length} tiles, {signs.length} visible signs, {warps.length} warp arrivals</title>
        {active.tiles.map(tile => urls.has(tile.filename) && <image key={tile.filename} href={urls.get(tile.filename)} x={tile.minX} y={tile.minZ} width={tile.maxX - tile.minX} height={tile.maxZ - tile.minZ} preserveAspectRatio="none" style={{ imageRendering: "pixelated" }} />)}
        {signs.map((sign, index) => <circle key={`${sign.signFingerprint || index}:${sign.x}:${sign.z}`} cx={sign.x} cy={sign.z} r={marker * .55} fill="#a5b4fc" stroke="#111827" strokeWidth={marker * .2}><title>{sign.itemName || "Chest shop"} · {sign.seller || "Unknown seller"} · Y {sign.y}</title></circle>)}
        {warps.map(warp => <path key={warp.id || warp.warpName} d={`M ${warp.x} ${warp.z-marker} L ${warp.x+marker} ${warp.z+marker*.8} L ${warp.x-marker} ${warp.z+marker*.8} Z`} fill="#fbbf24" stroke="#111827" strokeWidth={marker*.25}><title>/pw {warp.warpName} · Y {warp.y}</title></path>)}
      </svg>}
    </div>
    <div className="mt-2 flex flex-wrap items-center justify-center gap-x-4 gap-y-1 font-mono text-[10px] text-zinc-500">
      <span>{active.kind === "surface" ? "Surface mosaic" : `Layered cave at Y ${active.renderY}`}</span><span>{active.tiles.length} tile{active.tiles.length === 1 ? "" : "s"}</span><span>{signs.length} signs on this view</span><span>{warps.length} arrivals</span>
    </div>
  </div>;
}

function Coverage({ manifest, stale = false }) {
  const bounds = manifest?.bounds;
  const options = useMemo(() => layerOptions(manifest), [manifest]);
  if (!bounds) return null;
  const width = bounds.maxX - bounds.minX;
  const depth = bounds.maxZ - bounds.minZ;
  const missing = manifest.missingLayers || [];
  return <div className="grid grid-cols-2 gap-2 sm:grid-cols-4">
    <div className="rounded-lg border border-white/[0.07] bg-bg-deeper/70 p-3"><div className="font-mono text-[9px] uppercase text-zinc-600">Coverage</div><div className="mt-1 text-sm text-zinc-200">{width} × {depth}</div><div className="text-[10px] text-zinc-500">{Math.round(width * depth / 256)} chunks</div></div>
    <div className="rounded-lg border border-white/[0.07] bg-bg-deeper/70 p-3"><div className="font-mono text-[9px] uppercase text-zinc-600">Layers</div><div className="mt-1 text-sm text-zinc-200">{options.length}</div><div className="text-[10px] text-zinc-500">{options.filter(option => option.kind === "cave").length} cave views</div></div>
    <div className="rounded-lg border border-white/[0.07] bg-bg-deeper/70 p-3"><div className="font-mono text-[9px] uppercase text-zinc-600">Captured</div><div className="mt-1 truncate text-sm text-zinc-200">{formatDate(manifest.capturedAt)}</div><div className="text-[10px] text-zinc-500">In-game snapshot</div></div>
    <div className={`rounded-lg border p-3 ${stale || missing.length ? "border-amber-400/20 bg-amber-400/[0.04]" : "border-emerald-400/20 bg-emerald-400/[0.04]"}`}><div className="font-mono text-[9px] uppercase text-zinc-600">Readiness</div><div className={`mt-1 flex items-center gap-1.5 text-sm ${stale || missing.length ? "text-amber-300" : "text-emerald-300"}`}>{stale || missing.length ? <AlertTriangle className="h-3.5 w-3.5" /> : <CheckCircle2 className="h-3.5 w-3.5" />}{stale ? "Recapture" : missing.length ? `${missing.length} warning${missing.length === 1 ? "" : "s"}` : "Complete"}</div><div className="text-[10px] text-zinc-500">{stale ? "Shop layout changed" : "Full tile coverage"}</div></div>
  </div>;
}

function statusLabel(version, current) {
  if (current) return "Live";
  if (version.status === "ready") return "Ready to publish";
  if (version.status === "published") return "Previous version";
  return "Upload incomplete";
}

export default function AdminShopMaps({ data, onChanged }) {
  const [bundle, setBundle] = useState(null);
  const [reading, setReading] = useState(false);
  const [uploading, setUploading] = useState(false);
  const [progress, setProgress] = useState(0);
  const [error, setError] = useState(null);
  const [previewId, setPreviewId] = useState(null);
  const [confirmId, setConfirmId] = useState(null);
  const owner = data?.role === "owner";
  const groups = useMemo(() => {
    const result = new Map();
    for (const version of data?.versions || []) {
      const key = `${version.ownerType}:${version.ownerId}`;
      if (!result.has(key)) result.set(key, []);
      result.get(key).push(version);
    }
    return [...result.values()];
  }, [data?.versions]);

  const choose = async event => {
    const file = event.target.files?.[0];
    event.target.value = "";
    if (!file) return;
    setReading(true); setError(null); setBundle(null);
    try { setBundle(await readShopMapBundle(file)); }
    catch (next) { setError(next.message); }
    finally { setReading(false); }
  };

  const upload = async () => {
    if (!bundle || uploading) return;
    setUploading(true); setError(null); setProgress(0);
    try {
      const draft = await createShopMapDraft(bundle.manifest);
      const tiles = bundle.manifest.tiles;
      for (let index = 0; index < tiles.length; index += 1) {
        const tile = tiles[index];
        await uploadShopMapTile(draft.draftId, tile.filename, bundle.files.get(tile.filename));
        setProgress(Math.round(((index + 1) / tiles.length) * 100));
      }
      await finalizeShopMap(draft.draftId);
      setBundle(null);
      setPreviewId(draft.draftId);
      await onChanged("Map uploaded as a reviewable draft.");
    } catch (next) { setError(next.message); }
    finally { setUploading(false); }
  };

  const mutate = async (action, success) => {
    setError(null);
    try { await action(); setConfirmId(null); await onChanged(success); }
    catch (next) { setError(next.message); }
  };

  return <section className="space-y-5">
    <div className="rounded-2xl border border-white/10 bg-white/[0.025] p-5">
      <div className="flex flex-wrap items-start justify-between gap-4">
        <div><h2 className="font-heading text-xl font-bold">Publish shop terrain</h2><p className="mt-1 max-w-2xl text-sm text-zinc-400">Upload a bundle created by <code>/castia shopmap finish</code>. Review every captured layer before it replaces the live map.</p></div>
        {owner && <label className={`${button} cursor-pointer border border-indigo-400/30 bg-indigo-500/10 text-indigo-200 hover:bg-indigo-500/20`}>
          {reading ? <Loader2 className="animate-spin" /> : <UploadCloud />} Select bundle
          <input type="file" accept=".cmi-map.zip" className="sr-only" onChange={choose} />
        </label>}
      </div>
      <div className="mt-4 flex items-start gap-2 rounded-lg border border-sky-400/20 bg-sky-400/[0.04] p-3 text-xs text-sky-100"><CheckCircle2 className="mt-0.5 h-4 w-4 shrink-0 text-sky-300" /><span>Uploading and finalizing creates a private draft. The current public map remains online until you explicitly publish the replacement.</span></div>
      {!owner && <p className="mt-4 rounded-lg border border-amber-400/20 bg-amber-400/[0.05] p-3 text-xs text-amber-200">Map publication is restricted to the owner role.</p>}
      {error && <p role="alert" className="mt-4 rounded-lg border border-red-500/30 bg-red-500/10 p-3 text-sm text-red-200">{error}</p>}
      {bundle && <div className="mt-5 space-y-4">
        <div className="flex flex-wrap items-start justify-between gap-3"><div><div className="font-heading text-lg font-bold">{bundle.manifest.ownerName}</div><div className="mt-1 font-mono text-[10px] text-zinc-500">{bundle.manifest.ownerType} · {bundle.manifest.serverKey} · {bundle.manifest.dimensionKey}</div></div><button disabled={uploading} onClick={upload} className={`${button} min-w-44 bg-emerald-500 text-black hover:bg-emerald-400`}>{uploading ? <Loader2 className="animate-spin" /> : <UploadCloud />} {uploading ? `Uploading ${progress}%` : "Create private draft"}</button></div>
        <Coverage manifest={bundle.manifest} />
        <MapPreview bundle={bundle} />
      </div>}
    </div>

    {!groups.length && <div className="rounded-xl border border-dashed border-white/10 px-6 py-14 text-center"><Image className="mx-auto mb-3 text-zinc-600"/><div className="font-heading font-bold">No maps uploaded yet</div><p className="mt-1 text-xs text-zinc-500">Capture a classified shop warp in game to create the first terrain map.</p></div>}
    {groups.map(history => {
      const current = history.find(version => version.status === "published" && !version.retiredAt);
      return <article key={`${history[0].ownerType}:${history[0].ownerId}`} className="rounded-2xl border border-white/10 bg-white/[0.02] p-5">
        <div className="flex flex-wrap items-start justify-between gap-3"><div><h3 className="font-heading text-lg font-bold">{history[0].ownerName}</h3><p className="mt-1 font-mono text-[10px] text-zinc-500">{history[0].ownerType} · {history[0].dimensionKey} · {history.length} version{history.length === 1 ? "" : "s"}</p></div>
          <span className={`rounded-full border px-2.5 py-1 font-mono text-[9px] uppercase ${current ? current.stale ? "border-amber-400/30 text-amber-300" : "border-emerald-400/30 text-emerald-300" : "border-white/10 text-zinc-500"}`}>{current ? current.stale ? "Live · recapture recommended" : "Live map current" : "No live map"}</span></div>
        <div className="mt-4 space-y-2">{history.map(version => {
          const isCurrent = version.id === current?.id;
          const expanded = previewId === version.id;
          const caveYs = layerOptions(version.manifest).filter(option => option.kind === "cave").map(option => option.renderY);
          return <div key={version.id} className={`rounded-xl border ${isCurrent ? "border-emerald-400/20 bg-emerald-400/[0.025]" : version.status === "ready" ? "border-indigo-400/20 bg-indigo-400/[0.025]" : "border-white/[0.07] bg-bg-deeper/70"}`}>
            <div className="flex flex-wrap items-center justify-between gap-3 p-3">
              <div className="min-w-0"><div className="flex flex-wrap items-center gap-2"><span className="text-sm text-zinc-200">{statusLabel(version, isCurrent)}</span>{version.stale && <span className="rounded border border-amber-400/20 px-1.5 py-0.5 font-mono text-[8px] uppercase text-amber-300">layout changed</span>}</div><div className="mt-1 flex flex-wrap gap-x-3 gap-y-1 text-[10px] text-zinc-500"><span className="inline-flex items-center gap-1"><Clock3 className="h-3 w-3" /> Captured {formatDate(version.manifest?.capturedAt)}</span><span>{version.tiles?.length || 0} tiles</span>{caveYs.length > 0 && <span>Cave Y {caveYs.join(", ")}</span>}{version.publishedAt && <span>Published {formatDate(version.publishedAt)}</span>}</div></div>
              <div className="flex flex-wrap gap-2"><button onClick={() => setPreviewId(expanded ? null : version.id)} className={`${button} border border-white/10 text-zinc-300`}><Eye /> Preview {expanded ? <ChevronUp /> : <ChevronDown />}</button>
                {owner && version.status === "ready" && confirmId !== version.id && <button onClick={() => { setPreviewId(version.id); setConfirmId(version.id); }} className={`${button} bg-emerald-500 text-black`}>{current ? "Replace live map" : "Publish"}</button>}
                {owner && confirmId === version.id && <><button onClick={() => mutate(() => publishShopMap(version.id), current ? "Live map replaced." : "Map published.")} className={`${button} bg-emerald-500 text-black`}>Confirm publish</button><button onClick={() => setConfirmId(null)} className={`${button} border border-white/10 text-zinc-300`}>Cancel</button></>}
                {owner && version.status === "published" && version.retiredAt && <button onClick={() => mutate(() => rollbackShopMap(version.id), "Map version restored.")} className={`${button} border border-indigo-400/30 text-indigo-200`}><RotateCcw/> Restore</button>}
                {owner && !(version.status === "published" && !version.retiredAt) && <button aria-label="Delete map version" onClick={() => mutate(() => deleteShopMap(version.id), "Map version deleted.")} className={`${button} border border-red-500/20 text-red-300`}><Trash2/></button>}
              </div>
            </div>
            {expanded && <div className="space-y-3 border-t border-white/[0.07] p-3 sm:p-4">
              {confirmId === version.id && <div className="rounded-lg border border-amber-400/20 bg-amber-400/[0.05] p-3 text-xs text-amber-100">Review the imagery and marker alignment below. {current ? "Confirming will atomically replace the current public map; the existing map stays live if publication fails." : "Confirming will make this map visible on the public Shops page."}</div>}
              <Coverage manifest={version.manifest} stale={version.stale} />
              <MapPreview version={version} />
            </div>}
          </div>;
        })}</div>
      </article>;
    })}
  </section>;
}
