import { useState } from "react";
import { CheckCircle2, Loader2, ShieldCheck } from "lucide-react";
import { toast } from "sonner";
import { sendAdminMagicLink } from "@/lib/adminAuth";
import { fieldClass, buttonClass } from "./adminShared";

function LoginPanel() {
  const [email, setEmail] = useState("");
  const [sending, setSending] = useState(false);
  const [sent, setSent] = useState(false);

  const submit = async (event) => {
    event.preventDefault();
    setSending(true);
    try {
      await sendAdminMagicLink(email);
      setEmail("");
      setSent(true);
    } catch (error) {
      toast.error("Could not send sign-in link", { description: error.message });
    } finally {
      setSending(false);
    }
  };

  return <main className="min-h-[78vh] pt-32 pb-24 flex items-center">
    <div className="max-w-md w-full mx-auto px-6">
      <div className="bg-white/[0.025] border border-white/10 rounded-2xl p-7 shadow-2xl">
        <div className="w-11 h-11 rounded-xl bg-emerald-500/10 border border-emerald-500/30 grid place-items-center mb-5">
          <ShieldCheck className="w-5 h-5 text-emerald-400" />
        </div>
        <div className="font-mono text-[10px] uppercase tracking-[0.22em] text-emerald-400 mb-2">Restricted</div>
        <h1 className="font-heading text-3xl font-black tracking-tight mb-3">Area administration</h1>
        <p className="text-sm text-zinc-400 leading-relaxed mb-6">
          Sign in with an approved administrator email. The link expires, and this tab forgets the session when it closes.
        </p>
        {sent ? <div className="rounded-xl border border-emerald-500/30 bg-emerald-500/10 p-4">
          <div className="flex gap-3"><CheckCircle2 className="w-5 h-5 text-emerald-400 shrink-0" />
            <div><div className="text-sm font-semibold">Check your inbox</div>
              <p className="text-xs text-zinc-400 mt-1">Open the link in this browser. You can request another if it expires.</p></div>
          </div>
          <button className={`${buttonClass} border border-white/10 text-zinc-300 mt-4`} onClick={() => setSent(false)}>Use another email</button>
        </div> : <form onSubmit={submit} className="space-y-3">
          <label className="block text-[10px] font-mono uppercase tracking-wider text-zinc-500" htmlFor="admin-email">Admin email</label>
          <input id="admin-email" name="admin-email" type="email" autoComplete="off" required value={email} onChange={(event) => setEmail(event.target.value)} placeholder="you@example.com" className={fieldClass} />
          <button type="submit" disabled={sending} className={`${buttonClass} w-full bg-emerald-500 hover:bg-emerald-400 text-black`}>
            {sending && <Loader2 className="animate-spin" />} Email secure sign-in link
          </button>
        </form>}
      </div>
    </div>
  </main>;
}

export default LoginPanel;
