function Metric({ label, value, tone = "emerald" }) {
  return <div className="rounded-xl border border-white/10 bg-white/[0.025] p-4">
    <div className={`font-heading text-3xl font-black ${tone === "amber" ? "text-amber-400" : "text-emerald-400"}`}>{value ?? "—"}</div>
    <div className="mt-1 text-[10px] font-mono uppercase tracking-wider text-zinc-500">{label}</div>
  </div>;
}

export default Metric;
